// Manacher's algorithm - O(n) longest palindromic substring
function longestPalindrome(s) {
  const t = '#' + s.split('').join('#') + '#';   // unify even/odd length palindromes
  const n = t.length;
  const radius = new Array(n).fill(0);
  let center = 0, right = 0, best = 0, bestCenter = 0;

  for (let i = 0; i < n; i++) {
    if (i < right) {
      const mirror = 2 * center - i;
      radius[i] = Math.min(right - i, radius[mirror]);   // reuse mirrored radius
    }
    // try to expand past whatever was reused
    while (i - radius[i] - 1 >= 0 && i + radius[i] + 1 < n &&
           t[i - radius[i] - 1] === t[i + radius[i] + 1]) {
      radius[i]++;
    }
    if (i + radius[i] > right) {       // new rightmost palindrome found, update center/right
      center = i; right = i + radius[i];
    }
    if (radius[i] > best) { best = radius[i]; bestCenter = i; }
  }

  const start = (bestCenter - best) / 2;   // map back from transformed to original indices
  return s.substring(start, start + best);
}
